function updateClock(){const now=new Date();const clock=document.getElementById('jakarta-clock');const date=document.getElementById('jakarta-date');if(clock)clock.textContent=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Jakarta',hour:'2-digit',minute:'2-digit',hour12:false}).format(now);if(date)date.textContent=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Jakarta',weekday:'short',day:'numeric',month:'short'}).format(now)+' · UTC+7';}updateClock();if(document.getElementById('jakarta-clock'))setInterval(updateClock,30000);